// lib/rank/prompt.js

const DEFEATED_STATUS_SET = new Set(['defeated', 'lost', 'dead']);
const RETIRED_STATUS_SET = new Set([
  'retired',
  'eliminated',
  'out',
  'inactive',
  'spectator',
  'observer',
]);

function normalizeStatus(value) {
  if (!value && value !== 0) return 'unknown';
  if (typeof value === 'string') {
    const trimmed = value.trim().toLowerCase();
    return trimmed || 'unknown';
  }
  return String(value).trim().toLowerCase() || 'unknown';
}

function buildRoleKey(hero) {
  const role = typeof hero?.role === 'string' ? hero.role.trim().toLowerCase() : '';
  const side = typeof hero?.side === 'string' ? hero.side.trim().toLowerCase() : '';
  if (!role) return null;
  return `${role}::${side || 'any'}`;
}

function cloneHeroForSlot(hero, slotNo) {
  if (!hero) return null;
  const clone = { ...hero };
  if (slotNo != null) {
    clone.slot_no = slotNo;
    clone.slotNo = slotNo;
    const slotIndex = slotNo;
    clone.slot_index = slotIndex;
    clone.slotIndex = slotIndex;
    clone.slot_number = slotIndex + 1;
    clone.slotNumber = clone.slot_number;
  }
  return clone;
}

function buildFallbackPools(slotsMap = {}) {
  const pools = new Map();
  for (let s = 0; s < 12; s += 1) {
    const hero = slotsMap[s];
    if (!hero) continue;
    const key = buildRoleKey(hero);
    if (!key) continue;
    const entry = {
      hero,
      slotNo: s,
      slotNumber: s + 1,
      status: normalizeStatus(hero.status),
    };
    if (pools.has(key)) {
      pools.get(key).push(entry);
    } else {
      pools.set(key, [entry]);
    }
  }
  return pools;
}

function findFallbackHero({ pools, key, excludeHeroId }) {
  if (!key || !pools.has(key)) return null;
  const entries = pools.get(key) || [];
  const normalizedExclude = excludeHeroId ? String(excludeHeroId) : null;

  for (const entry of entries) {
    const heroId = entry?.hero?.hero_id ?? entry?.hero?.heroId ?? null;
    const normalizedHeroId = heroId != null ? String(heroId) : null;
    if (normalizedExclude && normalizedHeroId === normalizedExclude) {
      continue;
    }
    if (DEFEATED_STATUS_SET.has(entry.status) || RETIRED_STATUS_SET.has(entry.status)) {
      continue;
    }
    return entry;
  }

  return null;
}

function placeholderLabels(slotNo, useZeroBased = true) {
  const numeric = Number(slotNo);
  if (!Number.isFinite(numeric)) return [];
  if (useZeroBased) return [String(numeric)];
  return [String(numeric + 1)];
}

function clearSlotPlaceholders(text, slotNo) {
  if (!text) return '';
  let out = text;
  // Remove both zero-based and one-based labels that could reference this
  // slot index. For slot index N we remove {{slotN.*}} and {{slotN+1.*}}
  const labels = [String(Number(slotNo)), String(Number(slotNo) + 1)];
  labels.forEach(label => {
    const pattern = new RegExp(`\\{\\{slot${label}\\.[^}]+\\}\\}`, 'g');
    out = out.replace(pattern, '');
  });
  return out;
}

function applyHeroPlaceholders(text, hero, slotNo, useZeroBased = true) {
  if (!hero) {
    return clearSlotPlaceholders(text, slotNo);
  }

  let out = text;
  const labels = placeholderLabels(slotNo, useZeroBased);
  const zeroBasedValue = Number(slotNo);
  const oneBasedValue = zeroBasedValue + 1;
  // (no debug logging)
  labels.forEach(label => {
    out = out.replaceAll(`{{slot${label}.name}}`, hero.name ?? '');
    out = out.replaceAll(`{{slot${label}.description}}`, hero.description ?? '');
    for (let a = 1; a <= 12; a += 1) {
      out = out.replaceAll(`{{slot${label}.ability${a}}}`, hero[`ability${a}`] ?? '');
    }
    out = out.replaceAll(`{{slot${label}.role}}`, hero.role ?? '');
    out = out.replaceAll(`{{slot${label}.side}}`, hero.side ?? '');
    out = out.replaceAll(`{{slot${label}.status}}`, hero.status ?? '');
    out = out.replaceAll(`{{slot${label}.owner_id}}`, hero.owner_id ?? '');
    out = out.replaceAll(`{{slot${label}.ownerId}}`, hero.ownerId ?? '');

    const slotNoValue = hero.slotNo ?? hero.slot_no ?? zeroBasedValue;

    out = out.replaceAll(`{{slot${label}.slotNo}}`, slotNoValue);
    out = out.replaceAll(`{{slot${label}.slot_no}}`, slotNoValue);
    out = out.replaceAll(
      `{{slot${label}.slotNumber}}`,
      hero.slotNumber ?? hero.slot_number ?? oneBasedValue
    );
    out = out.replaceAll(
      `{{slot${label}.slot_number}}`,
      hero.slot_number ?? hero.slotNumber ?? oneBasedValue
    );
    out = out.replaceAll(
      `{{slot${label}.slotIndex}}`,
      hero.slotIndex ?? hero.slot_index ?? zeroBasedValue
    );
    out = out.replaceAll(
      `{{slot${label}.slot_index}}`,
      hero.slot_index ?? hero.slotIndex ?? zeroBasedValue
    );
    out = out.replaceAll(
      `{{slot${label}.name_or_role}}`,
      hero.name_or_role ?? hero.name ?? hero.role ?? ''
    );
    out = out.replaceAll(`{{slot${label}.display_name}}`, hero.display_name ?? hero.name ?? '');

    const keys = Object.keys(hero);
    keys.forEach(key => {
      const placeholder = `{{slot${label}.${key}}}`;
      if (out.includes(placeholder)) {
        out = out.replaceAll(placeholder, stringifyValue(hero[key]));
      }
    });
  });

  return out;
}

function resolveSlotHero({ slotNo, baseHero, pools }) {
  const meta = {
    baseHeroId: baseHero?.hero_id ?? baseHero?.heroId ?? null,
    baseStatus: normalizeStatus(baseHero?.status),
    slotNo,
    slotNumber: slotNo != null ? slotNo + 1 : null,
  };

  if (!baseHero) {
    return { hero: null, meta: { ...meta, skipped: true, reason: 'empty' } };
  }

  const key = buildRoleKey(baseHero);
  const status = meta.baseStatus;

  if (DEFEATED_STATUS_SET.has(status)) {
    return { hero: null, meta: { ...meta, skipped: true, reason: 'defeated' } };
  }

  if (RETIRED_STATUS_SET.has(status) || !baseHero.hero_id) {
    const fallback = findFallbackHero({
      pools,
      key,
      excludeHeroId: baseHero.hero_id ?? baseHero.heroId ?? null,
    });

    if (fallback) {
      const heroClone = cloneHeroForSlot(fallback.hero, slotNo);
      return {
        hero: heroClone,
        meta: {
          ...meta,
          replaced: true,
          fallbackFromSlot: fallback.slotNo,
          fallbackFromSlotNumber: fallback.slotNumber,
          fallbackHeroId: fallback.hero?.hero_id ?? fallback.hero?.heroId ?? null,
          fallbackStatus: fallback.status,
        },
      };
    }

    if (RETIRED_STATUS_SET.has(status)) {
      return { hero: null, meta: { ...meta, skipped: true, reason: 'retired' } };
    }
  }

  return {
    hero: cloneHeroForSlot(baseHero, slotNo),
    meta,
  };
}

export function compileTemplate({ template, slotsMap = {}, historyText = '' }) {
  if (!template) return { text: '', meta: {} };

  let out = template;
  const lines = (historyText || '').split(/\r?\n/);
  const last1 = lines.slice(-1).join('\n');
  const last2 = lines.slice(-2).join('\n');
  const pools = buildFallbackPools(slotsMap);
  const slotMeta = {};

  // Pre-scan template to detect whether each slot placeholder is used in
  // zero-based (slot0) or one-based (slot1) form. Prefer zero-based when
  // both present. This prevents earlier replacements from accidentally
  // overwriting placeholders intended for other slots.
  // no-op: input logging removed
  const slotLabelUsage = new Map();
  for (let s = 0; s < 12; s += 1) {
    const zeroLabel = new RegExp(`\\{\\{slot${s}\\.[^}]+\\}\\}`);
    const oneLabel = new RegExp(`\\{\\{slot${s + 1}\\.[^}]+\\}\\}`);
    const usesZero = zeroLabel.test(out);
    const usesOne = oneLabel.test(out);
    slotLabelUsage.set(s, usesZero ? 'zero' : usesOne ? 'one' : 'zero');
  }

  for (let s = 0; s < 12; s += 1) {
    const baseHero = slotsMap[s];
    const { hero, meta } = resolveSlotHero({ slotNo: s, baseHero, pools });
    if (meta) {
      slotMeta[s] = {
        ...meta,
        finalHeroId: hero?.hero_id ?? hero?.heroId ?? null,
        finalStatus: normalizeStatus(hero?.status),
      };
    }

    if (!hero) {
      // do not mutate the template here; let the single-pass resolver
      // handle missing heroes and produce empty substitutions.
      continue;
    }

    // Defer placeholder substitution to the single-pass resolver below to
    // avoid overlapping alias replacements when templates mix zero/one labels.
  }

  // Single-pass placeholder resolution to avoid alias collisions when templates
  // mix zero-based and one-based labels. We scan all {{slotN.key}} occurrences
  // and resolve each one independently by preferring one-based (N -> slot N-1)
  // when that target has a resolved hero, otherwise falling back to zero-based N.
  // no-op: before-replace logging removed

  out = out.replace(/\{\{slot(\d+)\.([^}]+)\}\}/g, (match, labelNumStr, key) => {
    const labelNum = Number(labelNumStr);
    if (!Number.isFinite(labelNum)) return '';

    // Decide whether this label should be interpreted as one-based or
    // zero-based by consulting the pre-scan slotLabelUsage. If the label
    // corresponds to one-based usage for the (labelNum-1) slot, prefer
    // mapping to that index first; otherwise prefer zero-based.
    const zeroIdx = labelNum;
    const oneIdx = labelNum - 1;
    const candidateIndices = [];
    const onePrefers = oneIdx >= 0 && slotLabelUsage.get(oneIdx) === 'one';
    if (onePrefers) {
      candidateIndices.push(oneIdx, zeroIdx);
    } else {
      candidateIndices.push(zeroIdx, oneIdx);
    }

    let resolved = null;
    for (const idx of candidateIndices) {
      if (!Number.isFinite(Number(idx)) || idx < 0) continue;
      const baseHero = slotsMap[idx];
      const { hero: resolvedHero } = resolveSlotHero({ slotNo: idx, baseHero, pools });
      if (resolvedHero) {
        resolved = { hero: resolvedHero, slotIndex: idx };
        break;
      }
    }

    if (!resolved) return '';

    // no-op: replacement logging removed

    const { hero: h, slotIndex } = resolved;
    const zeroBasedValue = Number(slotIndex);
    const oneBasedValue = zeroBasedValue + 1;

    // simple field resolution (mirrors applyHeroPlaceholders behavior)
    if (key === 'name') return h.name ?? '';
    if (key === 'description') return h.description ?? '';
    if (/^ability\d+$/.test(key)) return h[key] ?? '';
    if (key === 'role') return h.role ?? '';
    if (key === 'side') return h.side ?? '';
    if (key === 'status') return h.status ?? '';
    if (key === 'owner_id' || key === 'ownerId') return h.owner_id ?? h.ownerId ?? '';
    if (key === 'slotNo' || key === 'slot_no') return h.slotNo ?? h.slot_no ?? zeroBasedValue;
    if (key === 'slotNumber' || key === 'slot_number')
      return h.slotNumber ?? h.slot_number ?? oneBasedValue;
    if (key === 'slotIndex' || key === 'slot_index')
      return h.slotIndex ?? h.slot_index ?? zeroBasedValue;
    if (key === 'name_or_role') return h.name_or_role ?? h.name ?? h.role ?? '';
    if (key === 'display_name') return h.display_name ?? h.name ?? '';

    // fallback to any property on the hero object
    return stringifyValue(h[key]);
  });

  out = out.replaceAll('{{history.last1}}', last1);
  out = out.replaceAll('{{history.last2}}', last2);

  // 랜덤들
  out = out.replace(/\{\{random\.choice:([^}]+)\}\}/g, (_, g) => {
    const opts = g
      .split('|')
      .map(s => s.trim())
      .filter(Boolean);
    if (!opts.length) return '';
    return opts[Math.floor(Math.random() * opts.length)];
  });
  const randomSlotZero = Math.floor(Math.random() * 12);
  out = out.replaceAll('{{slot.random}}', String(randomSlotZero));
  out = out.replaceAll('{{slot.random_one_based}}', String(randomSlotZero + 1));
  out = out.replaceAll('{{slot.randomOneBased}}', String(randomSlotZero + 1));
  out = out.replaceAll(
    '{{random.ability}}',
    (() => {
      const abilityIndex = Math.floor(Math.random() * 12) + 1;
      const slotIndex = Math.floor(Math.random() * 12);
      return `{{slot${slotIndex}.ability${abilityIndex}}}`;
    })()
  );
  out = out.replaceAll(
    '{{random.ability_one_based}}',
    (() => {
      const abilityIndex = Math.floor(Math.random() * 12) + 1;
      const slotIndex = Math.floor(Math.random() * 12) + 1;
      return `{{slot${slotIndex}.ability${abilityIndex}}}`;
    })()
  );

  return { text: out, meta: { slots: slotMeta } };
}

function stringifyValue(value) {
  if (value === null || value === undefined) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }
  if (Array.isArray(value) || typeof value === 'object') {
    try {
      return JSON.stringify(value);
    } catch (error) {
      return '';
    }
  }
  return '';
}
